function onLoad()
    Global.call("setMatSnapPoints", self)
    self.interactable = false
end

deck_text = ""

function setDecklistFromPlaymat(player, value, index)
  deck_text = value
end

function closeImportViewPlaymat(player, value, index)
  self.UI.setXml("")
end

function importRiftboundDeckFromPlaymat(player, value, index)
  if deck_text=="" then
    broadcastToColor("Paste a Deck Code, TTS code, or Riftmana/Piltover URL to import.", player.color, {.9,.6,.3})
  else
    Global.call("importRiftboundDeckFromPlaymatRemote", {player=player, playmat=self, deck_text=deck_text})
  end
end

function InscriptRuneCountsRemote(params)
  InscriptRuneCounts(params.runeCounts)
end

function ImportFinished()
  self.UI.setXml("")
end

function InscriptRuneCounts(runeCounts)
  if #runeCounts>0 then
    updateRuneCountsUI(runeCounts)
  else
    self.UI.setXml("") -- clear UI
  end
end

function updateRuneCountsUI(runeCounts)
    runeCounts = runeCounts or {}

    local PANEL_WIDTH      = 3200
    local PANEL_HEIGHT     = 400
    local PANEL_SCALE      = 0.1
    local TITLE_FONT_SIZE  = 120
    local OUTLINE_SIZE     = 2
    local DEFAULT_TEXT_COLOR = "#FFFFFF"
    local DEFAULT_OUTLINE_COLOR = "rgba(0,0,0,1)"

    local function makeTextEntry(entry)
        entry = entry or {}
        return {
            tag = "Text",
            attributes = {
                text        = entry.count or "",
                fontSize    = TITLE_FONT_SIZE,
                color       = entry.text_color or DEFAULT_TEXT_COLOR,
                alignment   = "LowerCenter",
                wrap        = true,
                outline     = entry.outline_color or DEFAULT_OUTLINE_COLOR,
                outlineSize = OUTLINE_SIZE,
            }
        }
    end

    local children = {}
    for i = 1, 4 do
        table.insert(children, makeTextEntry(runeCounts[i]))
    end

    local panel = {
        tag = "Panel",
        attributes = {
            anchor   = "LowerMiddle",
            position = "0 80 -25",
            rotation = "0 0 180",
            width    = PANEL_WIDTH,
            height   = PANEL_HEIGHT,
            scale    = PANEL_SCALE,
        },
        children = {
            {
                tag = "HorizontalLayout",
                attributes = {
                    childForceExpandHeight = false,
                    childAlignment         = "LowerCenter",
                },
                children = children
            }
        }
    }

    self.UI.setXmlTable({ panel })
end

