function updateBattlefieldUI(title, effect)
    local PANEL_WIDTH      = 3000
    local PANEL_HEIGHT     = 400
    local PANEL_SCALE      = 0.1
    local TITLE_FONT_SIZE  = 80
    local EFFECT_FONT_SIZE = 60
    local TEXT_COLOR       = "#FFFFFF"
    local OUTLINE_COLOR    = "rgba(0,0,0,1)"

    local function makePanel(pos, rot)
        return {
            tag = "Panel",
