                anchor   = "LowerMiddle",
                position = pos,
                rotation = rot,
                width    = PANEL_WIDTH,
                height   = PANEL_HEIGHT,
                scale    = PANEL_SCALE,
            },
            children = {
                {
                    tag = "VerticalLayout",
                    attributes = {
                        childForceExpandHeight = false,
                        childAlignment         = "LowerCenter",
                    },
                    children = {
                        {
                            tag = "Text",
                            attributes = {
