                                fontSize = TITLE_FONT_SIZE,
                                color     = TEXT_COLOR,
                                alignment = "LowerCenter",
                                wrap      = true,
                                outline   = OUTLINE_COLOR,
                            }
                        },
                        {
                            tag = "Text",
                            attributes = {
                                text      = effect,
                                fontSize = EFFECT_FONT_SIZE,
                                color     = TEXT_COLOR,
                                alignment = "LowerCenter",
                                wrap      = true,
                                outline   = OUTLINE_COLOR,
                            }
                        },
                    }
                }
            }
        }
    end

    self.UI.setXmlTable({
        makePanel("0 67 -25", "0 0 180"),
        makePanel("0 -67 -25", "0 0 0"),
    })
